// Источник: web-тесты .qa/e2e/tests/reminders/rm-05-tefillin-row-days-israel.spec.ts, rm-06-tefillin-row-alot-to-shkiya.spec.ts,
// rm-07-tefillin-row-date-back-and-forth.spec.ts; план .qa/e2e/specs/reminders.md; кейсы .qa/tests/reminders/RM-05…RM-07.
// Тикет #3cc72778. В web даты/время подменялись page.clock — на устройстве часы не подменить, поэтому «ТОЛЬКО СЕГОДНЯ»:
// ожидание для текущего момента вычисляется по Hebcal API (тот же источник, что у экрана זמנים) для города профиля (פתח תקווה):
//   строка «הנחת תפילין / אל תשכח להניח היום עד השקיעה» есть ⇔ не שבת, не יום טוב / חול המועד / יום כיפור (Израиль)
//   и сейчас между עלות השחר (16.1°) и שקיעה; «הנחת תפילין» и «ראש חודש …» — без дублей.
// В пределах 3 минут от границы окна тест пропускается (момент неоднозначен).
import { $$, expect, driver } from '@wdio/globals';
import { byText, byLabelStartsWith, tapLabel, allByText, scrollToText } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';

const GEONAME_PETAH_TIKVA = 293918;
const TEFILLIN_TITLE = 'הנחת תפילין';
const TEFILLIN_TEXT = 'אל תשכח להניח היום עד השקיעה';

function israelToday(): string {
  return new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Jerusalem', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
}

async function hebcalJson(url: string): Promise<any> {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`Hebcal ${res.status}: ${url}`);
  return res.json();
}

/** Ожидание по Hebcal: день, когда надевают תפילין, и окно עלות השחר 16.1° – שקיעה. */
async function expectedForNow(day: string) {
  const z = await hebcalJson(`https://www.hebcal.com/zmanim?cfg=json&geonameid=${GEONAME_PETAH_TIKVA}&date=${day}`);
  const alot = new Date(z.times.alotHaShachar).getTime();
  const shkiya = new Date(z.times.sunset).getTime();
  const cal = await hebcalJson(
    `https://www.hebcal.com/hebcal?v=1&cfg=json&maj=on&min=off&mod=off&nx=off&ss=off&mf=off&c=off&i=on&start=${day}&end=${day}`,
  );
  const items: { title: string; yomtov?: boolean }[] = cal.items ?? [];
  const isShabbat = new Date(`${day}T12:00:00+03:00`).getUTCDay() === 6;
  const noTefillinDay = isShabbat || items.some((i) => i.yomtov || /CH''M|Chol ha-Moed|Yom Kippur/i.test(i.title));
  const now = Date.now();
  const margin = 3 * 60_000;
  const nearBoundary = Math.abs(now - alot) < margin || Math.abs(now - shkiya) < margin;
  const inWindow = now > alot && now < shkiya;
  return { tefillin: !noTefillinDay && inWindow, nearBoundary, info: { day, isShabbat, items: items.map((i) => i.title), alot: z.times.alotHaShachar, shkiya: z.times.sunset } };
}

function textsStartingWith(prefix: string) {
  return driver.isAndroid
    ? $$(`android=new UiSelector().textStartsWith("${prefix}")`)
    : $$(`-ios predicate string:label BEGINSWITH "${prefix}"`);
}

describe('Напоминания', () => {
  afterEach(async () => { await toHome(); });

  it('RM-05/06/07 «הנחת תפילין» в «תזכורות מהירות» — по календарю и окну עלות השחר–שקיעה на сегодня, без дублей #3cc72778 @prod-safe', async function () {
    // Предусловие: город профиля — פתח תקווה (как в web-тестах).
    await toHome();
    await tapLabel('מעבר לפרטים שלי');
    await (await byText('פרופיל אישי')).waitForDisplayed({ timeout: 20000 });
    await scrollToText('מיקום');
    const loc = await byLabelStartsWith('מיקום: ');
    const locLabel = (await loc.getAttribute(driver.isAndroid ? 'content-desc' : 'label')) ?? '';
    expect(locLabel).toContain('פתח תקווה');

    const exp = await expectedForNow(israelToday());
    if (exp.nearBoundary) this.skip();

    // Главная → блок «תזכורות מהירות».
    await toHome();
    await (await byText('תזכורות מהירות')).waitForDisplayed({ timeout: 25000 });
    const tefillin = await allByText(TEFILLIN_TITLE);
    expect(tefillin.length).toBe(exp.tefillin ? 1 : 0);
    if (exp.tefillin) await expect(byText(TEFILLIN_TEXT)).toBeDisplayed();

    // По одной строке «ראש חודש …» (фикс c695450).
    const rc = await textsStartingWith('ראש חודש');
    const titles: string[] = [];
    for (const el of rc) titles.push(await el.getText());
    expect(titles.filter((t, i) => titles.indexOf(t) !== i)).toEqual([]);
  });
});
